class Solution
{
public:
    int maxSubArrayLen(vector<int>& nums, int k)
    {
        unordered_map<long long, int> first;
        first[0] = -1;
        long long prefix = 0;
        int best = 0;
        for (int i = 0; i < (int)nums.size(); ++i)
        {
            prefix += nums[i];
            if (first.count(prefix - k))
            {
                best = max(best, i - first[prefix - k]);
            }
            if (!first.count(prefix)) first[prefix] = i;
        }
        return best;
    }
};
